'use strict';
const express=require('express'),crypto=require('crypto'),fs=require('fs'),path=require('path');const {db}=require('../db'),{DATA_DIR,APP_DIR}=require('../paths'),{renderFilm}=require('../filmMedia.cjs');const router=express.Router(),locks=new Set();
db.exec('CREATE TABLE IF NOT EXISTS film_projects(id TEXT PRIMARY KEY,payload TEXT NOT NULL,updated_at TEXT NOT NULL)');
function read(id){const r=db.prepare('SELECT payload FROM film_projects WHERE id=?').get(id);if(!r)throw Error('Không tìm thấy dự án phim.');return JSON.parse(r.payload)}
function save(p){p.updatedAt=new Date().toISOString();db.prepare('INSERT OR REPLACE INTO film_projects(id,payload,updated_at) VALUES(?,?,?)').run(p.id,JSON.stringify(p),p.updatedAt);return p}
function clean(p){const text=(v,max)=>String(v||'').slice(0,max),tags=v=>[...new Set((Array.isArray(v)?v:[]).map(x=>text(x,200)))].slice(0,5);if(!['16:9','9:16','1:1'].includes(p.ratio))throw Error('Tỷ lệ không hợp lệ.');if(!Array.isArray(p.scenes)||p.scenes.length<1||p.scenes.length>50)throw Error('Mỗi dự án cần từ 1–50 cảnh.');const scenes=p.scenes.map((s,i)=>{if(![5,10].includes(Number(s.duration)))throw Error('Mỗi cảnh chọn 5 hoặc 10 giây.');return {id:text(s.id||crypto.randomUUID(),80),episode:Math.max(1,Math.min(99,Number(s.episode)||1)),title:text(s.title||'Cảnh '+(i+1),150),prompt:text(s.prompt,8000),end:text(s.end,1000),duration:Number(s.duration),refTags:tags(s.refTags)}});if(new Set(scenes.map(s=>s.id)).size!==scenes.length)throw Error('Mã cảnh bị trùng.');return {title:text(p.title||'Phim mới',150),bible:text(p.bible,6000),ratio:p.ratio,refTags:tags(p.refTags),episodeRefs:Object.fromEntries(Object.entries(p.episodeRefs||{}).filter(([k])=>/^\d{1,2}$/.test(k)).map(([k,v])=>[k,tags(v)])),scenes,transition:p.transition==='cut'?'cut':'fade',audio:p.audio!==false}}
function withJobs(p){return {...p,scenes:p.scenes.map(s=>({...s,job:s.jobId?db.prepare('SELECT id,status,video_url,thumbnail_url,error,progress FROM jobs WHERE id=?').get(s.jobId)||{status:'missing'}:null}))}}
router.get('/',(req,res)=>res.json({projects:db.prepare('SELECT payload FROM film_projects ORDER BY updated_at DESC').all().map(r=>{const p=JSON.parse(r.payload);return {id:p.id,title:p.title,updatedAt:p.updatedAt,sceneCount:p.scenes.length}})}));
router.post('/',(req,res)=>{try{res.json(withJobs(save({id:'film_'+crypto.randomUUID(),...clean(req.body),exports:[]})))}catch(e){res.status(400).json({error:e.message})}});
router.get('/:id',(req,res)=>{try{res.json(withJobs(read(req.params.id)))}catch(e){res.status(404).json({error:e.message})}});
router.put('/:id',(req,res)=>{try{if(locks.has(req.params.id))throw Error('Dự án đang xử lý.');const old=read(req.params.id),next=clean(req.body);for(const scene of old.scenes.filter(s=>s.jobId)){const changed=next.scenes.find(s=>s.id===scene.id);if(!changed||JSON.stringify({...scene,jobId:undefined})!==JSON.stringify(changed))throw Error('Cảnh đã gửi được khóa. Thêm cảnh mới để tạo phiên bản khác.');}if(old.scenes.some(s=>s.jobId)&&(old.bible!==next.bible||old.ratio!==next.ratio||JSON.stringify(old.refTags)!==JSON.stringify(next.refTags)||JSON.stringify(old.episodeRefs)!==JSON.stringify(next.episodeRefs)))throw Error('Thông tin nhất quán và ảnh tham chiếu đã khóa sau khi gửi cảnh đầu tiên.');res.json(withJobs(save({...old,...next,scenes:next.scenes.map(s=>({...s,jobId:old.scenes.find(x=>x.id===s.id)?.jobId}))})))}catch(e){res.status(400).json({error:e.message})}});
async function local(req,url,body){const r=await fetch('http://127.0.0.1:'+req.socket.localPort+url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error||'Không gửi được cảnh.');return d}
router.post('/:id/generate',async(req,res)=>{const id=req.params.id;if(locks.has(id))return res.status(409).json({error:'Dự án đang xử lý.'});locks.add(id);try{const p=read(id),todo=p.scenes.filter(s=>!s.jobId);if(!todo.length)throw Error('Mọi cảnh đã được gửi.');if(todo.some(s=>!s.prompt.trim()))throw Error('Nhập kịch bản cho từng cảnh trước khi tạo.');for(const s of todo){const i=p.scenes.indexOf(s),prev=p.scenes[i-1],next=p.scenes[i+1],tags=[...new Set([...s.refTags,...(p.episodeRefs[s.episode]||[]),...p.refTags])];if(tags.length>5)throw Error('Cảnh '+s.title+' có hơn 5 ảnh tham chiếu. Chọn lại ảnh chung/tập/cảnh.');for(const tag of tags){const r=db.prepare('SELECT filepath,archived_at FROM ref_images WHERE tag=?').get(tag);if(!r||r.archived_at||!fs.existsSync(r.filepath))throw Error('Ảnh tham chiếu không còn: '+tag);}}
 for(const s of todo){const i=p.scenes.indexOf(s),prev=p.scenes[i-1],next=p.scenes[i+1],tags=[...new Set([...s.refTags,...(p.episodeRefs[s.episode]||[]),...p.refTags])],prompt=['FILM CONTINUITY CONTRACT. Use only this message and its attached references, never earlier chats.',`Film: ${p.title}. Episode ${s.episode}, scene ${i+1}: ${s.title}. One continuous shot, exactly ${s.duration} seconds, ${p.ratio}.`,tags.length?'Attached references in order: '+tags.map(t=>'@'+t+(s.refTags.includes(t)?' (this scene composition)':(p.episodeRefs[s.episode]||[]).includes(t)?' (episode setting)':' (shared identity / wardrobe)')).join(', '):'Text-to-video; use no earlier image.', 'LOCKED STORY BIBLE: '+p.bible,'Preserve shared character face, age, body, hair, wardrobe, props, environment geography, screen direction, lighting, color palette and time of day. Scene references set composition; shared references fix identity. No unrelated subjects or old references.',prev?'PREVIOUS SCENE CONTEXT: '+prev.prompt+'\nPREVIOUS END STATE: '+(prev.end||'Match action and screen direction from prior scene.'):'Establish the film setting and characters.', 'THIS SCENE: '+s.prompt,'END STATE TO HAND OFF: '+(s.end||'Stable final pose and framing for the next scene.'),next?'NEXT SCENE CONTEXT: '+next.prompt:'Conclude the film or episode naturally.','Match action at opening/ending; ease motion in and out, preserve screen direction and exposure. No titles, overlays or unnecessary cuts.'].join('\n');const spec={mediaType:'video',prompts:[prompt],refTags:tags,ratio:p.ratio,duration:s.duration,clientContext:{prompt,ratio:p.ratio,duration:s.duration,mode:'film-scene',references:tags.map(tag=>({tag}))}};const guard=await local(req,'/api/queue/preflight',spec);if(guard.errors?.length)throw Error(guard.errors.join('\n'));if(guard.warnings?.length)throw Error(guard.warnings.join('\n'));const d=await local(req,'/api/queue/enqueue',spec);s.jobId=d.jobs[0].id;save(p);}
 await local(req,'/api/queue/process',{});res.json(withJobs(p));}catch(e){res.status(400).json({error:e.message})}finally{locks.delete(id)}});
router.post('/:id/export',(req,res)=>{const id=req.params.id;if(locks.has(id))return res.status(409).json({error:'Dự án đang xử lý.'});let p,entry,clips;try{p=read(id);const episode=req.body.episode?Number(req.body.episode):null,scenes=p.scenes.filter(s=>!episode||s.episode===episode);if(!scenes.length)throw Error('Không có cảnh trong tập này.');clips=scenes.map(s=>{const j=s.jobId&&db.prepare('SELECT status,video_url FROM jobs WHERE id=?').get(s.jobId);if(!j||j.status!=='completed'||!/^\/videos\/[^/]+\.mp4$/.test(j.video_url||''))throw Error('Cảnh '+s.title+' chưa có video hoàn thành.');const file=path.join(DATA_DIR,'videos',path.basename(j.video_url));if(!fs.existsSync(file))throw Error('File video không còn: '+s.title);return {file,duration:s.duration}});entry={id:crypto.randomUUID(),status:'rendering',progress:0,episode,transition:p.transition,audio:p.audio,createdAt:new Date().toISOString()};p.exports.push(entry);save(p);locks.add(id);res.status(202).json(withJobs(p));}catch(e){return res.status(400).json({error:e.message})}
 (async()=>{let work,out;try{const dir=path.join(DATA_DIR,'videos');work=fs.mkdtempSync(path.join(dir,'film_work_'));const name='film_'+entry.id+'.mp4';out=path.join(dir,name);const ffmpeg=require(path.join(APP_DIR,'vendor/media/node_modules/ffmpeg-static')).replace(/app\.asar([/\\])/,'app.asar.unpacked$1');const result=await renderFilm({ffmpeg,clips,out,work,ratio:p.ratio,transition:entry.transition,audio:entry.audio,onProgress:n=>{entry.progress=n;save(p)}});entry.status='completed';entry.progress=100;entry.url='/videos/'+name;entry.duration=result.duration;save(p);}catch(e){entry.status='failed';entry.error=e.message;save(p);if(out)fs.rmSync(out,{force:true});}finally{if(work)fs.rmSync(work,{recursive:true,force:true});locks.delete(id)}})();});
for(const row of db.prepare('SELECT payload FROM film_projects').all()){const p=JSON.parse(row.payload);let changed=false;for(const e of p.exports||[])if(e.status==='rendering'){e.status='failed';e.error='App đã đóng trong lúc ghép. Bấm ghép lại.';changed=true}if(changed)save(p)}
module.exports=router;
